CREATE OR REPLACE FUNCTION public.crm_location_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid:=nullif(_data->>'id','')::uuid; cid uuid:=(_data->>'customer_id')::uuid; old jsonb; BEGIN PERFORM 1 FROM crm_customers WHERE id=cid FOR UPDATE; IF NOT crm_customer_editable(cid) THEN RAISE EXCEPTION 'Không có quyền sửa địa điểm.'; END IF; IF i IS NOT NULL THEN SELECT to_jsonb(c) INTO old FROM crm_locations c WHERE id=i AND customer_id=cid FOR UPDATE; IF old IS NULL THEN RAISE EXCEPTION 'Địa điểm không thuộc khách này.'; END IF; END IF; IF coalesce((_data->>'is_primary')::boolean,false) THEN UPDATE crm_locations SET is_primary=false WHERE customer_id=cid; END IF; IF i IS NULL THEN INSERT INTO crm_locations(customer_id) VALUES(cid) RETURNING id INTO i; END IF; UPDATE crm_locations SET label=coalesce(nullif(_data->>'label',''),'Văn phòng'),province_code=nullif(_data->>'province_code',''),ward_code=nullif(_data->>'ward_code',''),address=coalesce(_data->>'address',''),is_primary=coalesce((_data->>'is_primary')::boolean,false),active=coalesce((_data->>'active')::boolean,true) WHERE id=i; INSERT INTO crm_events(customer_id,actor_id,action,before_data,after_data) SELECT cid,auth.uid(),'location_save',old,to_jsonb(c) FROM crm_locations c WHERE id=i; RETURN i; END $$;
CREATE OR REPLACE FUNCTION public.crm_template_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid:=nullif(_data->>'id','')::uuid; shared boolean:=coalesce((_data->>'shared')::boolean,false); BEGIN IF NOT crm_can(auth.uid(),'biz.crm_use') OR (shared AND NOT crm_can(auth.uid(),'biz.crm_settings')) THEN RAISE EXCEPTION 'Không có quyền lưu mẫu chăm sóc.'; END IF; IF trim(coalesce(_data->>'name',''))='' OR coalesce((_data->>'interval_days')::int,0)<1 THEN RAISE EXCEPTION 'Tên mẫu và chu kỳ không hợp lệ.'; END IF; IF i IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm_templates WHERE id=i AND (owner_id=auth.uid() OR crm_can(auth.uid(),'biz.crm_settings'))) THEN RAISE EXCEPTION 'Không có quyền sửa mẫu.'; END IF; IF i IS NULL THEN INSERT INTO crm_templates(owner_id,name) VALUES(CASE WHEN shared THEN NULL ELSE auth.uid() END,_data->>'name') RETURNING id INTO i; END IF; UPDATE crm_templates SET name=_data->>'name',goal=coalesce(_data->>'goal',''),channel=coalesce(_data->>'channel','phone'),interval_days=(_data->>'interval_days')::int,group_id=nullif(_data->>'group_id','')::uuid,active=coalesce((_data->>'active')::boolean,true) WHERE id=i; INSERT INTO crm_events(actor_id,action,after_data) VALUES(auth.uid(),'template_save',_data); RETURN i; END $$;
CREATE OR REPLACE FUNCTION public.crm_people() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT crm_can(auth.uid(),'biz.crm_use') THEN RAISE EXCEPTION 'Không có quyền CRM.'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name,'department_id',d.id,'department',d.name,'system_id',d.system_id,'system',sys.name,'team_id',t.id,'team',t.name) ORDER BY p.full_name),'[]') FROM profiles p LEFT JOIN biz_departments d ON d.id=crm_department(p.id) LEFT JOIN biz_systems sys ON sys.id=d.system_id LEFT JOIN LATERAL (SELECT tm.team_id FROM biz_team_members tm WHERE tm.user_id=p.id AND tm.started_at<=now() AND (tm.ended_at IS NULL OR tm.ended_at>now()) ORDER BY tm.started_at DESC LIMIT 1) tm ON true LEFT JOIN biz_teams t ON t.id=tm.team_id WHERE crm_can(p.id,'biz.crm_use') AND crm_owner_visible(p.id)); END $$;
CREATE OR REPLACE FUNCTION public.crm_read(_mine boolean DEFAULT true,_owner uuid DEFAULT NULL,_search text DEFAULT '',_archived boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE customers jsonb; schedules jsonb; contacts jsonb; BEGIN IF NOT crm_can(auth.uid(),'biz.crm_use') OR (NOT _mine AND NOT crm_can(auth.uid(),'biz.crm_view_scope')) THEN RAISE EXCEPTION 'Bạn không có quyền xem CRM trong phạm vi này.'; END IF; SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.updated_at DESC),'[]') INTO customers FROM crm_customers c WHERE crm_owner_visible(c.owner_id) AND (NOT _mine OR c.owner_id=auth.uid()) AND (_owner IS NULL OR c.owner_id=_owner) AND (c.archived_at IS NOT NULL)=_archived AND (_search='' OR c.name ILIKE '%'||_search||'%' OR c.phone ILIKE '%'||_search||'%' OR c.code ILIKE '%'||_search||'%' OR EXISTS(SELECT 1 FROM crm_contacts ct WHERE ct.customer_id=c.id AND (ct.name ILIKE '%'||_search||'%' OR ct.phone ILIKE '%'||_search||'%'))); SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.due_at),'[]') INTO schedules FROM crm_schedules s WHERE s.customer_id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(customers) x) AND crm_owner_visible(s.owner_id,s.department_id,s.attributed_at); SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') INTO contacts FROM crm_contacts c WHERE c.customer_id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(customers) x); RETURN jsonb_build_object('customers',customers,'schedules',schedules,'contacts',contacts,'server_now',now()); END $$;
CREATE OR REPLACE FUNCTION public.crm_detail(_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT crm_customer_visible(_id) THEN RAISE EXCEPTION 'Hồ sơ không tồn tại hoặc bạn không có quyền xem.'; END IF; RETURN jsonb_build_object('customer',(SELECT to_jsonb(c) FROM crm_customers c WHERE id=_id),'contacts',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY is_primary DESC,created_at),'[]') FROM crm_contacts c WHERE customer_id=_id),'locations',(SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY is_primary DESC),'[]') FROM crm_locations l WHERE customer_id=_id),'schedules',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY due_at),'[]') FROM crm_schedules s WHERE customer_id=_id AND crm_owner_visible(s.owner_id,s.department_id,s.attributed_at)),'interactions',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY happened_at DESC),'[]') FROM crm_interactions i WHERE customer_id=_id AND crm_owner_visible(i.owner_id,i.department_id,i.happened_at)),'events',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY created_at DESC),'[]') FROM crm_events e WHERE customer_id=_id),'can_edit',crm_customer_editable(_id)); END $$;
CREATE OR REPLACE FUNCTION public.crm_duplicates(_name text DEFAULT '',_phone text DEFAULT '',_tax text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT crm_can(auth.uid(),'biz.crm_use') THEN RAISE EXCEPTION 'Không có quyền CRM.'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name)),'[]') FROM (SELECT id,code,name FROM crm_customers c WHERE crm_owner_visible(c.owner_id) AND ((trim(_name)<>'' AND lower(trim(name))=lower(trim(_name))) OR (_phone<>'' AND regexp_replace(phone,'[^0-9]','','g')=regexp_replace(_phone,'[^0-9]','','g')) OR (_tax<>'' AND tax_code=_tax)) LIMIT 10) q); END $$;
CREATE OR REPLACE FUNCTION public.crm_report(_start date,_end date,_mine boolean DEFAULT true,_owner uuid DEFAULT NULL,_group uuid DEFAULT NULL,_province text DEFAULT NULL,_department uuid DEFAULT NULL,_system uuid DEFAULT NULL,_team uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE lo timestamptz:=_start::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'; hi timestamptz:=least((_end+1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh',now()); customers jsonb; schedules jsonb; interactions jsonb; totals jsonb; BEGIN IF NOT crm_can(auth.uid(),'biz.crm_use') OR (NOT _mine AND NOT crm_can(auth.uid(),'biz.crm_view_scope')) OR _start>_end OR _end-_start>3660 THEN RAISE EXCEPTION 'Kỳ hoặc phạm vi báo cáo không hợp lệ.'; END IF; WITH snapshots AS (SELECT c.id,c.owner_id current_owner,coalesce((SELECT e.after_data FROM crm_events e WHERE e.customer_id=c.id AND e.action IN ('customer_save','transfer','archive','restore') AND e.created_at<hi ORDER BY e.created_at DESC,e.id DESC LIMIT 1),to_jsonb(c)) data FROM crm_customers c WHERE c.created_at<hi AND crm_owner_visible(c.owner_id)), selected AS (SELECT x.*,(data->>'owner_id')::uuid owner FROM snapshots x WHERE data->>'archived_at' IS NULL AND (_group IS NULL OR (data->>'group_id')::uuid=_group) AND (_province IS NULL OR data->>'province_code'=_province)) SELECT coalesce(jsonb_agg(data),'[]') INTO customers FROM selected x WHERE crm_owner_visible(owner,crm_department(owner,hi),hi) AND (NOT _mine OR owner=auth.uid()) AND (_owner IS NULL OR owner=_owner) AND (_department IS NULL OR crm_department(owner,hi)=_department) AND (_system IS NULL OR EXISTS(SELECT 1 FROM biz_department_system_history h WHERE h.department_id=crm_department(owner,hi) AND h.system_id=_system AND h.started_at<hi AND (h.ended_at IS NULL OR h.ended_at>=hi))) AND (_team IS NULL OR EXISTS(SELECT 1 FROM biz_team_members tm WHERE tm.user_id=owner AND tm.team_id=_team AND tm.started_at<hi AND (tm.ended_at IS NULL OR tm.ended_at>=hi)));
SELECT coalesce(jsonb_agg(to_jsonb(s) || jsonb_build_object('status',CASE WHEN s.processed_at>=hi OR s.processed_at IS NULL THEN 'pending' ELSE s.status END,'processed_at',CASE WHEN s.processed_at<hi THEN s.processed_at ELSE NULL END,'completed_at',CASE WHEN s.completed_at<hi THEN s.completed_at ELSE NULL END)),'[]') INTO schedules FROM crm_schedules s WHERE s.customer_id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(customers) x) AND s.created_at<hi AND crm_owner_visible(s.owner_id,s.department_id,s.attributed_at) AND (NOT _mine OR s.owner_id=auth.uid()) AND (_owner IS NULL OR s.owner_id=_owner);
SELECT coalesce(jsonb_agg(to_jsonb(i)),'[]') INTO interactions FROM crm_interactions i WHERE i.customer_id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(customers) x) AND i.happened_at>=lo AND i.happened_at<hi AND crm_owner_visible(i.owner_id,i.department_id,i.happened_at) AND (NOT _mine OR i.owner_id=auth.uid()) AND (_owner IS NULL OR i.owner_id=_owner);
WITH cs AS (SELECT x FROM jsonb_array_elements(customers) x), ss AS (SELECT x,(x->>'original_due_at')::timestamptz due FROM jsonb_array_elements(schedules) x), ii AS (SELECT x FROM jsonb_array_elements(interactions) x) SELECT jsonb_build_object('customers',(SELECT count(*) FROM cs),'new_customers',(SELECT count(*) FROM cs WHERE (x->>'created_at')::timestamptz>=lo),'priority_customers',(SELECT count(*) FROM cs JOIN crm_catalogs cat ON cat.id=(x->>'priority_id')::uuid WHERE coalesce((cat.config->>'key_customer')::boolean,false)),'scheduled_customers',(SELECT count(*) FROM cs WHERE EXISTS(SELECT 1 FROM ss WHERE ss.x->>'customer_id'=cs.x->>'id' AND ss.x->>'status'='pending')),'due',(SELECT count(*) FROM ss WHERE due>=lo AND due<hi),'processed',(SELECT count(*) FROM ss WHERE due>=lo AND due<hi AND x->>'processed_at' IS NOT NULL),'on_time',(SELECT count(*) FROM ss WHERE due>=lo AND due<hi AND (x->>'completed_at')::timestamptz<=due),'overdue',(SELECT count(*) FROM ss WHERE due<hi AND x->>'status'='pending'),'overdue_customers',(SELECT count(DISTINCT x->>'customer_id') FROM ss WHERE due<hi AND x->>'status'='pending'),'priority_overdue',(SELECT count(*) FROM cs JOIN crm_catalogs cat ON cat.id=(cs.x->>'priority_id')::uuid WHERE coalesce((cat.config->>'key_customer')::boolean,false) AND EXISTS(SELECT 1 FROM ss WHERE ss.x->>'customer_id'=cs.x->>'id' AND due<hi AND ss.x->>'status'='pending')),'attempts',(SELECT count(*) FROM ii),'connected',(SELECT count(*) FROM ii WHERE (x->>'connected')::boolean)) INTO totals;
RETURN jsonb_build_object('customers',customers,'schedules',schedules,'interactions',interactions,'totals',totals,'start',_start,'end',_end,'as_of',hi,'server_now',now()); END $$;
CREATE OR REPLACE FUNCTION public.crm_file_allowed(_name text,_write boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN IF split_part(_name,'/',1)!~'^[0-9a-fA-F-]{36}$' THEN RETURN false; END IF; cid:=split_part(_name,'/',1)::uuid; RETURN CASE WHEN _write THEN crm_customer_editable(cid) ELSE crm_customer_visible(cid) END; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END $$;
CREATE POLICY crm_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='crm-files' AND crm_file_allowed(name));
CREATE POLICY crm_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='crm-files' AND crm_file_allowed(name,true));
DO $$ DECLARE r record; BEGIN FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'crm_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',r.fn); EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,service_role',r.fn); END LOOP; END $$;